//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::hash::hash_str`; the
//! native twin is `benches/native/Bench/HashStr.lean`.
//! the seed-11 call; the Rust operand passes through black_box so the hash of the fixed string is
//! not hoisted out of the loop

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::hash;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &String, n: u64) -> u64 {
    let s = inp.as_bytes();
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, hash::hash_str(black_box(s), 11));
    }
    acc
}

fn main() {
    run(|| mixed(), kernel)
}
